// Authed root for the phone app. The monitor screen itself is the claude-design
// export (MobileMonitor.jsx); this file just renders it and keeps the login
// screen the AuthGate shows before there's a session. Swapping in a new design
// export = replace MobileMonitor.jsx; this wrapper and the seam stay put.
import React from 'react';
import { login } from '../src/api.js';
import MobileMonitor from './MobileMonitor.jsx';
import { UpdateBar } from './updater.jsx';
import { MachineBar } from './machine-address.jsx';

export default function App({ onChangeMachine }) {
  // UpdateBar and MachineBar are host-owned chrome (install prompt / self-update
  // banner; which machine this app points at). Both render nothing when there's
  // nothing to offer — MachineBar only in the standalone build — so they never
  // intrude on the design's own screen. MobileMonitor stays the pristine export.
  return (
    <>
      <UpdateBar />
      <MobileMonitor />
      <MachineBar onChange={onChangeMachine} />
    </>
  );
}

// --- Login screen ----------------------------------------------------------
// Same token flow as the LCD UI (POST /auth/login via api.js). Shown by the
// AuthGate in main.jsx when there's no valid session.
export function Login({ onDone }) {
  const [pw, setPw] = React.useState('');
  const [remember, setRemember] = React.useState(true);
  const [err, setErr] = React.useState('');
  const [busy, setBusy] = React.useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true); setErr('');
    const r = await login(pw, remember);
    setBusy(false);
    if (r.ok) onDone();
    else if (r.status === 0) setErr('Backend unreachable.');
    else setErr('Wrong password.');
  };

  return (
    <div className="login">
      <h1>FT2</h1>
      <p>Sign in to monitor the machine.</p>
      <form onSubmit={submit}>
        <input type="password" inputMode="text" autoComplete="current-password"
          placeholder="Password" value={pw} onChange={(e) => setPw(e.target.value)} autoFocus />
        <label className="remember">
          <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} />
          Remember this phone
        </label>
        <div className="err">{err}</div>
        <button className="btn primary" style={{ width: '100%' }} disabled={busy || !pw}>
          {busy ? 'Signing in…' : 'Sign in'}
        </button>
      </form>
    </div>
  );
}
