// PWA entry. Registers the service worker (installability + app-shell cache),
// then mounts an AuthGate that shows the Login screen until there's a valid
// session, exactly like the LCD UI's gate but phone-shaped.
import React from 'react';
import { createRoot } from 'react-dom/client';
import { checkAuth } from '../src/api.js';
import App, { Login } from './App.jsx';
import { MachineSetup, needsSetup, STANDALONE, machineLabel, forgetMachine } from './machine-address.jsx';

function AuthGate() {
  // 'setup' | 'checking' | 'ok' | 'login' | 'offline'
  // 'setup' only ever happens in the standalone (off-machine) build: the app has
  // no API at its own origin, so it must be told which machine to talk to first.
  const [gate, setGate] = React.useState(() => (needsSetup() ? 'setup' : 'checking'));

  const verify = React.useCallback(async () => {
    setGate('checking');
    setGate(await checkAuth());
  }, []);

  // Re-point at another machine (or re-enter the address after a typo).
  const changeMachine = React.useCallback(() => { forgetMachine(); setGate('setup'); }, []);

  React.useEffect(() => { if (gate !== 'setup') verify(); }, [verify]);

  // api.js fires this when any request 401s (token expired/cleared) → re-gate.
  React.useEffect(() => {
    const onAuth = () => setGate('login');
    window.addEventListener('ft2-auth-required', onAuth);
    return () => window.removeEventListener('ft2-auth-required', onAuth);
  }, []);

  if (gate === 'setup') return <MachineSetup onDone={verify} />;
  if (gate === 'checking') {
    return <div className="login"><p className="muted center">Connecting…</p></div>;
  }
  if (gate === 'offline') {
    // Hosted off-machine, this is the normal state when the machine is powered
    // down or you're off the tailnet — the app itself still opens, which is the
    // whole point of not being served by the machine.
    return (
      <div className="login">
        <h1>FT2</h1>
        <p>
          {STANDALONE
            ? `Can't reach ${machineLabel()}. Check that Tailscale is on and the machine is powered.`
            : "Can't reach the machine. Check that you're on the Tailscale network."}
        </p>
        <button className="btn" style={{ width: '100%' }} onClick={verify}>Retry</button>
        {STANDALONE && (
          <button className="btn ghost" style={{ width: '100%', marginTop: 10 }}
            onClick={changeMachine}>Change machine address</button>
        )}
      </div>
    );
  }
  if (gate === 'login') return <Login onDone={() => setGate('ok')} />;
  return <App onChangeMachine={changeMachine} />;
}

// Service worker: scoped to /m/ (it's served from /m/sw.js). Best-effort — the
// app works without it, this only adds installability + offline app-shell.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch(() => { /* non-fatal */ });
  });
}

createRoot(document.getElementById('root')).render(<AuthGate />);
