import React from "react";
// Live seam: the host-owned hook (mobile-core.jsx) replaces the exported mock.
import { useMobileTelemetry } from "./mobile-core.jsx";

// FT2 Mobile Monitor — phone-first, portrait/landscape, read-only.
// Single seam: useMobileTelemetry() below — swap it for the live feed hook.
const M = {
  bg: '#0a0c0e', panel: '#141820', line: '#262d38',
  text: '#e7edf3', muted: '#8a97a7',
  accent: '#4aa8ff', ok: '#37d67a', warn: '#ffb020', bad: '#ff5964',
  mono: '"JetBrains Mono", ui-monospace, monospace',
  sans: '"Space Grotesk", system-ui, sans-serif',
};

M.violet = '#a78bfa';

// ─── host-owned station states → readout colour ──────────────────────────
// The host classifies each station (same thresholds as the LCD); the phone only
// maps state → colour. Unknown/missing state reads as 'off' (neutral), never a
// fake green.
const STATE_COLOR = {
  off: M.muted,
  heating: M.warn, attemp: M.ok, overtemp: M.bad,          // heaters
  building: M.warn, atpressure: M.ok, deviation: M.bad,    // pump
  atspeed: M.ok, offspeed: M.bad,                          // puller
  ok: M.ok, drift: M.warn, stall: M.bad, unstable: M.violet, // dancers
};
const DANCER_LABEL = { off: 'OFF', ok: 'OK', drift: 'DRIFT', unstable: 'RETUNE', stall: 'STALL' };

const stateColor = (s) => STATE_COLOR[s] || M.muted;

// ─── formatting: missing → em-dash, never a fake zero ────────────────────
const has = (v) => v !== undefined && v !== null && !(typeof v === 'number' && Number.isNaN(v));
const num = (v, d = 0) => (has(v) ? Number(v).toFixed(d) : '—');
const int = (v) => (has(v) ? String(Math.round(v)) : '—');

const STATES = {
  IDLE: { c: M.muted, label: 'Idle' },
  RUNNING: { c: M.ok, label: 'Running' },
  PAUSED: { c: M.warn, label: 'Paused' },
  HOMING: { c: M.accent, label: 'Homing' },
  ESTOP: { c: M.bad, label: 'E-stop' },
  FAULT: { c: M.bad, label: 'Fault' },
  DISCONNECTED: { c: M.muted, label: 'Disconnected' },
};

// ─── primitives ──────────────────────────────────────────────────────────
function Panel({ title, right, children, style }) {
  return (
    <section style={{ background: M.panel, border: `1px solid ${M.line}`, borderRadius: 14, overflow: 'hidden', ...style }}>
      {title ? (
        <header style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 14px', borderBottom: `1px solid ${M.line}` }}>
          <span style={{ fontFamily: M.mono, fontSize: 10, letterSpacing: '0.16em', color: M.muted, textTransform: 'uppercase' }}>{title}</span>
          <span style={{ flex: 1 }} />
          {right}
        </header>
      ) : null}
      <div style={{ padding: 14 }}>{children}</div>
    </section>
  );
}

function Readout({ label, value, unit, sub, color, size = 'md' }) {
  const fs = { sm: 'clamp(20px,6vw,26px)', md: 'clamp(26px,8vw,34px)', lg: 'clamp(34px,11vw,46px)' }[size];
  return (
    <div style={{ minWidth: 0 }}>
      <div style={{ fontFamily: M.mono, fontSize: 10, letterSpacing: '0.14em', color: M.muted, textTransform: 'uppercase', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 5, marginTop: 4 }}>
        <span style={{ fontFamily: M.mono, fontSize: fs, fontWeight: 500, lineHeight: 1, color: color || M.text, fontVariantNumeric: 'tabular-nums' }}>{value}</span>
        {unit ? <span style={{ fontFamily: M.mono, fontSize: 12, color: M.muted }}>{unit}</span> : null}
      </div>
      {sub ? <div style={{ fontFamily: M.mono, fontSize: 11, color: M.muted, marginTop: 4, fontVariantNumeric: 'tabular-nums' }}>{sub}</div> : null}
    </div>
  );
}

function Bar({ pct, color }) {
  const w = has(pct) ? Math.max(0, Math.min(100, pct)) : 0;
  return (
    <div style={{ height: 10, borderRadius: 999, background: '#0a0e14', border: `1px solid ${M.line}`, overflow: 'hidden' }}>
      <div style={{ width: `${w}%`, height: '100%', background: color || M.accent, borderRadius: 999, transition: 'width .4s ease' }} />
    </div>
  );
}

function AckButton({ color, onClick }) {
  return (
    <button onClick={onClick} style={{
      flexShrink: 0, alignSelf: 'center', minHeight: 44, padding: '0 12px', borderRadius: 9, cursor: 'pointer',
      background: 'transparent', color, border: `1px solid ${color}`,
      fontFamily: M.mono, fontSize: 10, letterSpacing: '0.1em', textTransform: 'uppercase',
    }}>Acknowledge</button>
  );
}

function Banner({ tone, text, onAck }) {
  const c = { bad: M.bad, warn: M.warn, muted: M.muted }[tone] || M.warn;
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, minHeight: 46, padding: '8px 10px 8px 14px', borderRadius: 12, background: `color-mix(in oklab, ${c} 16%, ${M.panel})`, border: `1px solid ${c}` }}>
      <span style={{ width: 9, height: 9, borderRadius: '50%', background: c, flexShrink: 0 }} />
      <span style={{ flex: 1, fontFamily: M.sans, fontSize: 14, fontWeight: 600, color: M.text, textWrap: 'pretty' }}>{text}</span>
      {onAck ? <AckButton color={c} onClick={onAck} /> : null}
    </div>
  );
}

// Two-column layout once the app's own box is wide enough (landscape phone,
// tablet, or the preview host's landscape frame). Measured, not matchMedia,
// so it works inside a sized container too.
function useWideBox(ref) {
  const [on, setOn] = React.useState(false);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => setOn(el.getBoundingClientRect().width >= 560);
    measure();
    const ro = new ResizeObserver(() => requestAnimationFrame(measure));
    ro.observe(el.parentElement || el);
    window.addEventListener('resize', measure);
    return () => { ro.disconnect(); window.removeEventListener('resize', measure); };
  }, []);
  return on;
}

function PromptBanner({ severity, title, text, onAck }) {
  const c = severity === 'danger' ? M.bad : M.warn;
  return (
    <div style={{ display: 'flex', gap: 10, padding: '9px 10px 9px 14px', borderRadius: 12, background: `color-mix(in oklab, ${c} 18%, ${M.panel})`, border: `1px solid ${c}` }}>
      <span style={{ width: 9, height: 9, borderRadius: '50%', background: c, flexShrink: 0, marginTop: 7 }} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontFamily: M.sans, fontSize: 14, fontWeight: 700, color: M.text, textWrap: 'pretty' }}>{title}</div>
        {text ? <div style={{ fontFamily: M.sans, fontSize: 13, lineHeight: 1.4, color: M.muted, marginTop: 3, textWrap: 'pretty' }}>{text}</div> : null}
      </div>
      {onAck ? <AckButton color={c} onClick={onAck} /> : null}
    </div>
  );
}

// ─── screen ──────────────────────────────────────────────────────────────
function App() {
  const [camFull, setCamFull] = React.useState(false);
  const [camZoom, setCamZoom] = React.useState({ s: 1, x: 0, y: 0 });
  const [acked, setAcked] = React.useState({});
  const ack = (id) => setAcked((prev) => ({ ...prev, [id]: true }));
  const rootRef = React.useRef(null);
  const wide = useWideBox(rootRef);
  const full = { gridColumn: '1 / -1' };
  const raw = useMobileTelemetry();
  const d = raw;

  const t = d.t || {};
  const st = STATES[d.state] || STATES.IDLE;
  const stale = !d.fresh || !d.connected;
  // Show the Run panel off the host RUN STATE MACHINE (t.run.phase), not the
  // machine state: `d.state` mirrors the firmware's own state, which is just
  // "is any motor stepping" — it flips to IDLE between moves and has no PAUSED,
  // so it hid the panel during a real run. Older host with no run state → fall
  // back to the machine state so nothing regresses.
  const runPhase = t.run && t.run.phase;
  const running = runPhase
    ? runPhase !== 'idle'
    : (d.state === 'RUNNING' || d.state === 'PAUSED');

  const banners = [];
  if (!d.fresh) banners.push({ id: 'stale', tone: 'warn', text: 'Link stale — readings may be old' });
  if (d.state === 'ESTOP') banners.push({ id: 'estop', tone: 'bad', text: 'E-STOP engaged' });
  if (d.state === 'FAULT' || d.faultCode > 0) banners.push({ id: 'fault', tone: 'bad', text: `Fault: ${d.faultMessage || `code ${d.faultCode}`}` });
  if (t.materialLow) banners.push({ id: 'material-low', tone: 'warn', text: 'Material low — refill soon' });

  // Acknowledged notices hide until their condition clears and returns; an ack is
  // local to the phone (the host owns the condition itself).
  const live = [...banners.map((b) => b.id), ...(d.userPrompts || []).map((p) => p.id)];
  const shownBanners = banners.filter((b) => !acked[b.id]);
  const shownPrompts = (d.userPrompts || []).filter((p) => !acked[p.id]);
  React.useEffect(() => {
    setAcked((prev) => {
      const next = {};
      let changed = false;
      Object.keys(prev).forEach((k) => { if (live.includes(k)) next[k] = true; else changed = true; });
      return changed ? next : prev;
    });
  }, [live.join('|')]);

  const tempRows = [
    { k: 'extruder', label: 'Extruder', v: t.tempExtruder, set: t.extruderSet, state: t.extruderHeatState },
    { k: 'tube', label: 'Tube heater', v: t.tempTube, set: t.tubeSet, state: t.preHeaterState },
  ];
  const flowRows = [
    { k: 'material', label: 'Material', v: t.materialFlow, d: 2 },
    { k: 'thixo', label: 'Thixo', v: t.thixoFlow, d: 2 },
    { k: 'total', label: 'Total', v: t.totalFlow, d: 2 },
  ];
  // Dancer motor health — the gram readouts were dropped; the state is the signal.
  const motorRows = [
    { k: 'feeder', label: 'Feeder', state: t.feederTensionState },
    { k: 'collector', label: 'Collector', state: t.collectorTensionState },
  ];
  const fanRows = [
    { k: 'caseFan', label: 'Case', on: t.caseFan },
    { k: 'extruderFan', label: 'Extruder', on: t.extruderFan },
    { k: 'tubeFan', label: 'Tube', on: t.tubeFan },
  ];

  return (
    <div ref={rootRef} style={{ minHeight: '100dvh', background: M.bg, color: M.text, fontFamily: M.sans, WebkitTextSizeAdjust: '100%', overflowX: 'clip' }}>
      <div style={{ position: 'sticky', top: 0, zIndex: 5, background: 'rgba(10,12,14,0.92)', backdropFilter: 'blur(8px)', borderBottom: `1px solid ${M.line}` }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, minHeight: 52, padding: '0 14px' }}>
          <img src="uploads/Filament2_icon.png" alt="" style={{ height: 24, width: 'auto', display: 'block', flexShrink: 0 }} />
          <span style={{ fontFamily: M.mono, fontSize: 12, letterSpacing: '0.14em', color: M.muted }}>FT2</span>
          <span style={{ flex: 1 }} />
          <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontFamily: M.mono, fontSize: 11, letterSpacing: '0.1em', color: stale ? M.warn : M.muted }}>
            <span style={{ width: 8, height: 8, borderRadius: '50%', background: stale ? M.warn : M.ok, animation: stale ? 'none' : 'ft2m-pulse 2s ease-in-out infinite' }} />
            {stale ? 'STALE' : 'LIVE'}
          </span>
          <span style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '6px 10px', borderRadius: 999, background: M.panel, border: `1px solid ${M.line}` }}>
            <span style={{ width: 8, height: 8, borderRadius: '50%', background: st.c }} />
            <span style={{ fontFamily: M.mono, fontSize: 11, fontWeight: 600, letterSpacing: '0.1em', color: M.text, textTransform: 'uppercase' }}>{st.label}</span>
          </span>
        </div>
        {shownBanners.length || shownPrompts.length ? (
          <div style={{ display: 'grid', gap: 8, padding: '0 14px 12px' }}>
            {shownBanners.map((b) => <Banner key={b.id} tone={b.tone} text={b.text} onAck={() => ack(b.id)} />)}
            {shownPrompts.map((p) => <PromptBanner key={p.id} severity={p.severity} title={p.title} text={p.text} onAck={() => ack(p.id)} />)}
          </div>
        ) : null}
      </div>

      <main style={{ display: 'grid', gridTemplateColumns: wide ? 'repeat(2,minmax(0,1fr))' : '1fr', alignContent: 'start', gap: 12, padding: 14, paddingBottom: 'calc(88px + env(safe-area-inset-bottom))' }}>
        {running ? (
          <Panel style={wide ? undefined : full} title={(t.run && t.run.label) || 'Run'}
            right={t.run && t.run.message
              ? <span style={{ fontFamily: M.mono, fontSize: 10, letterSpacing: '0.12em', color: M.muted, textTransform: 'uppercase' }}>{t.run.message}</span>
              : null}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
              {/* Metres THIS RUN (host run_seg_m) — not filledKm, which is the
                  spool's cumulative total and barely moves during one run. */}
              <span style={{ fontFamily: M.mono, fontSize: 'clamp(34px,12vw,48px)', lineHeight: 1, fontWeight: 500, fontVariantNumeric: 'tabular-nums' }}>{num(t.runMeters, 1)}</span>
              <span style={{ fontFamily: M.mono, fontSize: 14, color: M.muted }}>m</span>
              <span style={{ flex: 1 }} />
              {has(t.filledKm) ? <span style={{ fontFamily: M.mono, fontSize: 12, color: M.muted, fontVariantNumeric: 'tabular-nums' }}>{num(t.filledKm, 2)} km total</span> : null}
            </div>
            {t.run && t.run.prompt ? <div style={{ marginTop: 12 }}><Banner tone="warn" text={t.run.prompt} /></div> : null}
          </Panel>
        ) : null}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(140px,100%),1fr))', gap: 12 }}>
          <Panel><Readout label="Pressure" value={num(t.pressurePsi, 0)} unit="psi" size="lg" color={stateColor(t.pumpState)} sub={t.pumpState === 'off' ? 'set —' : `set ${num(t.pressureSet, 0)}`} /></Panel>
          <Panel><Readout label="Line speed" value={num(t.lineSpeed, 1)} unit="m/min" size="lg" color={stateColor(t.pullerState)} sub={`HDPE ${num(t.extrusionMmSec, 1)} mm/sec`} /></Panel>
        </div>

        <Panel title="Pump flow · ml/min">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 10 }}>
            {flowRows.map((r) => <Readout key={r.k} label={r.label} value={num(r.v, r.d)} size="sm" />)}
          </div>
        </Panel>

        <Panel title="Heaters">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 10 }}>
            {tempRows.map((r) => (
              <Readout key={r.k} label={r.label} value={num(r.v, 0)} unit="°C" color={stateColor(r.state)}
                sub={r.state === 'off' ? 'set —' : `set ${num(r.set, 0)}`} />
            ))}
          </div>
        </Panel>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(168px,100%),1fr))', gap: 12 }}>
        <Panel title="Remaining material" right={t.materialLow ? <span style={{ fontFamily: M.mono, fontSize: 10, letterSpacing: '0.12em', color: M.warn }}>LOW</span> : null}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
            <span style={{ fontFamily: M.mono, fontSize: 'clamp(26px,8vw,34px)', lineHeight: 1, fontVariantNumeric: 'tabular-nums', color: t.materialLow ? M.warn : M.text }}>{num(t.materialKg, 1)}</span>
            <span style={{ fontFamily: M.mono, fontSize: 12, color: M.muted }}>kg</span>
            <span style={{ flex: 1 }} />
            <span style={{ fontFamily: M.mono, fontSize: 14, color: M.muted, fontVariantNumeric: 'tabular-nums' }}>{int(t.materialPct)}%</span>
          </div>
          <div style={{ marginTop: 10 }}><Bar pct={t.materialPct} color={t.materialLow ? M.warn : M.accent} /></div>
        </Panel>

        <Panel title="Remaining tube">
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
            <span style={{ fontFamily: M.mono, fontSize: 'clamp(26px,8vw,34px)', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>{int(t.tubeRemainingM)}</span>
            <span style={{ fontFamily: M.mono, fontSize: 12, color: M.muted }}>m</span>
          </div>
          <div style={{ fontFamily: M.mono, fontSize: 11, color: M.muted, marginTop: 10, fontVariantNumeric: 'tabular-nums' }}>{has(t.remainingMin) ? `~${int(t.remainingMin)} min left` : 'on feeder'}</div>
        </Panel>
        </div>

        <Panel style={wide ? { ...full, order: 1 } : undefined} title="Camera" right={<span style={{ fontFamily: M.mono, fontSize: 10, letterSpacing: '0.12em', color: t.cameraUrl ? M.ok : M.muted }}>{t.cameraUrl ? 'LIVE' : 'OFFLINE'}</span>}>
          <div onClick={() => setCamFull(true)} role="button" style={{ position: 'relative', aspectRatio: wide ? '16 / 6' : '4 / 3', borderRadius: 10, overflow: 'hidden', background: '#05070a', border: `1px solid ${M.line}`, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
            {t.cameraUrl
              ? <img src={t.cameraUrl} alt="Live camera" style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', transform: `translate(${(camZoom.fx || 0) * 100}%, ${(camZoom.fy || 0) * 100}%) scale(${camZoom.s})`, transformOrigin: 'center' }} />
              : <span style={{ fontFamily: M.mono, fontSize: 11, letterSpacing: '0.12em', color: '#4d5765' }}>NO SIGNAL</span>}
            <span style={{ position: 'absolute', right: 8, bottom: 8, padding: '4px 9px', borderRadius: 6, background: 'rgba(10,12,14,0.72)', fontFamily: M.mono, fontSize: 10, letterSpacing: '0.1em', color: M.muted }}>TAP TO EXPAND</span>
          </div>
        </Panel>

        <Panel title="Motor health">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 10 }}>
            {motorRows.map((r) => {
              const c = stateColor(r.state);
              return (
                <div key={r.k} style={{ display: 'flex', alignItems: 'center', gap: 8, minHeight: 44, padding: '0 12px', borderRadius: 10, background: '#0f131a', border: `1px solid ${r.state && r.state !== 'off' && r.state !== 'ok' ? c : M.line}` }}>
                  <span style={{ width: 8, height: 8, borderRadius: '50%', background: c, flexShrink: 0 }} />
                  <span style={{ fontFamily: M.mono, fontSize: 12, color: M.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.label}</span>
                  <span style={{ flex: 1 }} />
                  <span style={{ fontFamily: M.mono, fontSize: 11, letterSpacing: '0.08em', color: c }}>{DANCER_LABEL[r.state] || '—'}</span>
                </div>
              );
            })}
          </div>
        </Panel>

        <Panel title="Fans">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(132px,100%),1fr))', gap: 10 }}>
            {fanRows.map((f) => (
              <div key={f.k} style={{ display: 'flex', alignItems: 'center', gap: 8, minHeight: 44, padding: '0 12px', borderRadius: 10, background: '#0f131a', border: `1px solid ${has(f.on) && f.on ? M.ok : M.line}` }}>
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: !has(f.on) ? M.muted : f.on ? M.ok : '#39414d', flexShrink: 0 }} />
                <span style={{ fontFamily: M.mono, fontSize: 12, color: M.text, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{f.label}</span>
                <span style={{ flex: 1 }} />
                <span style={{ fontFamily: M.mono, fontSize: 11, color: !has(f.on) ? M.muted : f.on ? M.ok : M.muted }}>{!has(f.on) ? '—' : f.on ? 'ON' : 'OFF'}</span>
              </div>
            ))}
          </div>
        </Panel>

        <footer style={{ ...full, order: 2, display: 'flex', justifyContent: 'space-between', gap: 10, padding: '2px 2px 0', fontFamily: M.mono, fontSize: 11, color: M.muted }}>
          <span>app {d.hostVersion || '—'} · fw {d.fwVersion || '—'}</span>
          <span>{t.ip || '—'}</span>
        </footer>
      </main>

      {/* Reserved action zone — stays empty until commands ship */}
      <div className="ft2-actionbar" style={{ position: 'fixed', left: 0, right: 0, bottom: 0, zIndex: 4, background: 'rgba(10,12,14,0.94)', backdropFilter: 'blur(8px)', borderTop: `1px solid ${M.line}`, padding: `12px 14px calc(12px + env(safe-area-inset-bottom))` }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 48, borderRadius: 12, border: `1px dashed ${M.line}`, fontFamily: M.mono, fontSize: 11, letterSpacing: '0.12em', color: M.muted }}>MONITOR ONLY</div>
      </div>

      {camFull ? <CameraFullscreen url={t.cameraUrl} zoom={camZoom} onZoom={setCamZoom} onClose={() => setCamFull(false)} /> : null}

      <style>{`@keyframes ft2m-pulse{0%,100%{opacity:1}50%{opacity:.35}} a{color:${M.accent}}a:hover{color:${M.text}}`}</style>
    </div>
  );
}

// Landscape fullscreen camera. Portrait phones get the frame rotated 90° so the
// feed fills the long axis; landscape devices show it upright.
function CameraFullscreen({ url, onClose, zoom, onZoom }) {
  const [portrait, setPortrait] = React.useState(() => window.innerHeight > window.innerWidth);
  React.useEffect(() => {
    const f = () => setPortrait(window.innerHeight > window.innerWidth);
    window.addEventListener('resize', f);
    if (screen.orientation && screen.orientation.lock) { try { screen.orientation.lock('landscape'); } catch (e) {} }
    return () => {
      window.removeEventListener('resize', f);
      if (screen.orientation && screen.orientation.unlock) { try { screen.orientation.unlock(); } catch (e) {} }
    };
  }, []);
  const stage = portrait
    ? { width: '100dvh', height: '100dvw', transform: 'translate(-50%,-50%) rotate(90deg)' }
    : { width: '100%', height: '100%', transform: 'translate(-50%,-50%)' };

  // pinch / wheel zoom + drag pan, clamped so the frame can't be flung away
  const [z, setZ] = React.useState(zoom || { s: 1, x: 0, y: 0 });
  React.useEffect(() => { if (onZoom) onZoom(z); }, [z]);
  const g = React.useRef({ pts: new Map(), d0: 0, s0: 1, ox: 0, oy: 0, moved: false });
  const clamp = (n) => ({ s: n.s, x: n.s <= 1 ? 0 : n.x, y: n.s <= 1 ? 0 : n.y, fx: n.s <= 1 ? 0 : (n.fx || 0), fy: n.s <= 1 ? 0 : (n.fy || 0) });
  const down = (e) => { if (e.target.closest('button')) return; g.current.pts.set(e.pointerId, e); g.current.moved = false; try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {}
    if (g.current.pts.size === 2) { const [a, b] = [...g.current.pts.values()]; g.current.d0 = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY); g.current.s0 = z.s; }
    else { g.current.ox = e.clientX - z.x; g.current.oy = e.clientY - z.y; } };
  const move = (e) => {
    if (!g.current.pts.has(e.pointerId)) return;
    g.current.pts.set(e.pointerId, e); g.current.moved = true;
    if (g.current.pts.size === 2) { const [a, b] = [...g.current.pts.values()]; const d = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
      if (g.current.d0) setZ((p) => clamp({ ...p, s: Math.min(6, Math.max(1, g.current.s0 * (d / g.current.d0))) })); }
    else if (z.s > 1) setZ((p) => { const x = e.clientX - g.current.ox, y = e.clientY - g.current.oy; return { ...p, x, y, fx: x / Math.max(1, window.innerWidth), fy: y / Math.max(1, window.innerHeight) }; });
  };
  const up = (e) => { g.current.pts.delete(e.pointerId); if (g.current.pts.size < 2) g.current.d0 = 0; };
  const wheel = (e) => { setZ((p) => clamp({ ...p, s: Math.min(6, Math.max(1, p.s * (e.deltaY < 0 ? 1.12 : 0.89))) })); };
  const dbl = () => { clearTimeout(g.current.tap); setZ((p) => clamp(p.s > 1 ? { s: 1, x: 0, y: 0, fx: 0, fy: 0 } : { s: 2.5, x: 0, y: 0, fx: 0, fy: 0 })); };
  // single tap closes, but only after the double-tap window has passed
  const tap = (e) => {
    if (e.target.closest('button')) return;
    if (g.current.moved || z.s > 1) return;
    clearTimeout(g.current.tap);
    g.current.tap = setTimeout(onClose, 280);
  };
  React.useEffect(() => () => clearTimeout(g.current.tap), []);

  return (
    <div onClick={tap} onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} onWheel={wheel} onDoubleClick={dbl}
      style={{ position: 'fixed', inset: 0, zIndex: 50, background: '#000', touchAction: 'none', overflow: 'hidden', cursor: z.s > 1 ? 'grab' : 'zoom-in' }}>
      <div style={{ position: 'absolute', top: '50%', left: '50%', transformOrigin: 'center', ...stage, transform: `translate(calc(-50% + ${z.x}px), calc(-50% + ${z.y}px)) ${portrait ? 'rotate(90deg) ' : ''}scale(${z.s})` }}>
        {url ? <img src={url} alt="Live camera" draggable="false" style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', userSelect: 'none' }} /> : null}
        {!url ? <span style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: M.mono, fontSize: 12, letterSpacing: '0.14em', color: '#4d5765' }}>NO SIGNAL</span> : null}
      </div>
      {z.s > 1 ? <span style={{ position: 'absolute', left: '50%', transform: 'translateX(-50%)', bottom: 'calc(14px + env(safe-area-inset-bottom))', padding: '5px 10px', borderRadius: 6, background: 'rgba(10,12,14,0.72)', fontFamily: M.mono, fontSize: 11, color: M.muted, pointerEvents: 'none' }}>{z.s.toFixed(1)}× · drag to pan</span> : null}
      <button onClick={(e) => { e.stopPropagation(); clearTimeout(g.current.tap); onClose(); }} onPointerDown={(e) => e.stopPropagation()} style={{ position: 'absolute', top: 'calc(14px + env(safe-area-inset-top))', right: 'calc(14px + env(safe-area-inset-right))', zIndex: 1, minWidth: 44, minHeight: 44, borderRadius: 10, border: `1px solid ${M.line}`, background: 'rgba(10,12,14,0.7)', color: M.text, fontFamily: M.mono, fontSize: 16, cursor: 'pointer' }}>✕</button>
    </div>
  );
}

export default App;
export { App as MobileMonitor };
