// Mobile data seam. Reuses the host contract verbatim via ../src/api.js (same
// /ws feed, same /status seed, same Bearer-token auth) and maps the raw frame to
// the small set of display fields the phone UI shows. Field conversions mirror
// webui/src/live-core.jsx so the phone and the LCD never disagree on a number.
//
// Monitor-only today, but control-ready: ../src/controls.js `dispatchControl`
// and the live-core action helpers are already the write path — the future
// "essential control" phase adds buttons that call them, no re-architecting.
import React from 'react';
import { subscribeTelemetry, subscribeState, apiGet, getToken, apiUrl } from '../src/api.js';
// Same colour-state logic as the LCD (shared module) so the phone and the panel
// never disagree on a colour. Pump state has memory → one instance for this UI.
import { heaterState, pullerState, makePumpState } from '../src/schematic-state.js';
const _pumpState = makePumpState();

const PSI_PER_BAR = 14.5038;
const n1 = (v) => (typeof v === 'number' ? +v.toFixed(1) : undefined);
const n2 = (v) => (typeof v === 'number' ? +v.toFixed(2) : undefined);

// MJPEG camera stream, token in the query (an <img> can't set the Authorization
// header — the /camera/stream endpoint accepts ?token). apiUrl() makes it
// absolute when the app is hosted off-machine; same-origin otherwise. Stable
// string across frames (the token doesn't change) so the <img> never reloads.
function cameraUrl() {
  const tk = getToken();
  return apiUrl(tk ? `/camera/stream?token=${encodeURIComponent(tk)}` : '/camera/stream');
}

// Raw /ws (or /status.telemetry) frame → flat display object. Everything is
// optional: a field the host doesn't send stays undefined and the UI shows "—".
export function mapTelemetry(d) {
  if (!d) return {};
  return {
    pressurePsi:   typeof d.pressure_bar === 'number' ? +(d.pressure_bar * PSI_PER_BAR).toFixed(1) : undefined,
    pressureSet:   n1(d.pump_pressure_psi),       // commanded pressure setpoint, psi (get_setpoints)
    tempExtruder:  n1(d.temperature_c),
    tempTube:      n1(d.preheater_temp_c),
    extruderSet:   typeof d.extruder_active_target_c === 'number' && d.extruder_active_target_c > 0 ? d.extruder_active_target_c : undefined,
    tubeSet:       typeof d.preheater_active_target_c === 'number' && d.preheater_active_target_c > 0 ? d.preheater_active_target_c : undefined,
    lineSpeed:     n2(d.line_speed_m_per_min),   // m/min (native host unit)
    // Live HDPE extrusion speed (mm/s): extruder = motor idx 1, deg/s → mm/s via
    // the calibration-derived lead (mirrors live-core's motor mm conversion).
    extrusionMmSec: (Array.isArray(d.motor_speeds) && typeof d.motor_speeds[1] === 'number'
                     && typeof d.extruder_mm_per_rev === 'number')
      ? +((d.motor_speeds[1] / 360) * d.extruder_mm_per_rev).toFixed(2) : undefined,
    tensionFeeder:    n1(d.feeder_gr),
    tensionCollector: n1(d.collector_gr),
    // Colour states — identical to the LCD. Heater/pump/puller computed from the
    // shared module; dancer tension states arrive as host-computed frame fields.
    preHeaterState:   heaterState(d.preheater_enabled, d.preheater_temp_c, d.preheater_active_target_c),
    extruderHeatState: heaterState(d.extruder_enabled, d.temperature_c, d.extruder_active_target_c),
    pumpState:        _pumpState(d.pump_on, typeof d.pressure_bar === 'number' ? d.pressure_bar * PSI_PER_BAR : undefined, d.pump_pressure_psi),
    pullerState:      pullerState(d.line_speed_m_per_min, d.puller_speed_m_per_min),
    feederTensionState:    typeof d.feeder_tension_state === 'string' ? d.feeder_tension_state : undefined,
    collectorTensionState: typeof d.collector_tension_state === 'string' ? d.collector_tension_state : undefined,
    materialFlow:  n2(d.material_flow_ml_min),
    thixoFlow:     n2(d.thixo_flow_ml_min),
    totalFlow:     n2(d.total_flow_ml_min),
    materialKg:    n2(d.material_remaining_kg),
    materialPct:   n1(d.material_pct),
    materialLow:   typeof d.material_low === 'boolean' ? d.material_low : undefined,
    // Run state machine (host RunController): {phase,step,prompt,message,...}.
    run:           d.run || undefined,
    // Metres produced in the CURRENT running segment (host-owned: zeroed on
    // start/resume, held through a pause) — the Run panel's headline number.
    // Same field the LCD Run tab shows, so phone and panel never disagree.
    runMeters:     typeof d.run_seg_m === 'number' ? d.run_seg_m : undefined,
    progressPct:   n1(d.progress_pct),
    filledKm:      n2(d.filled_km),
    targetKm:      n2(d.target_km),
    remainingMin:  typeof d.remaining_min === 'number' ? Math.round(d.remaining_min) : undefined,
    // Unfilled tube left on the feeder spool (m) — the design's "tube remaining".
    tubeRemainingM: typeof d.feeder_remaining_m === 'number' ? Math.round(d.feeder_remaining_m) : undefined,
    cameraUrl:     cameraUrl(),
    caseFan:       !!d.case_fan,
    extruderFan:   !!d.extruder_fan,
    tubeFan:       !!d.tube_fan,
    extruderHeating:  !!d.extruder_heating,
    preheaterHeating: !!d.preheater_heating,
    ip:            typeof d.ip === 'string' ? d.ip : undefined,
  };
}

const STALE_MS = 2000; // telemetry older than this → link not fresh (memory rule)

// The single hook the phone UI consumes.
//   t          — mapped display fields (see mapTelemetry)
//   state       — machine state string (IDLE/RUNNING/ESTOP/FAULT/…)
//   fresh       — telemetry arrived within the last STALE_MS (honest link state)
//   faultCode   — from the /status seed (stale until a fresh /status)
export function useMobileTelemetry() {
  const [t, setT] = React.useState({});
  const [state, setState] = React.useState(null);
  const [fresh, setFresh] = React.useState(false);
  const [status, setStatus] = React.useState(null);
  const [userPrompts, setUserPrompts] = React.useState([]);
  const lastRef = React.useRef(0);

  // Live /ws frame → hold the latest; a render tick samples + maps it so we
  // never re-render faster than the eye needs.
  const liveRef = React.useRef(null);
  React.useEffect(() => subscribeTelemetry((d) => {
    liveRef.current = d;
    lastRef.current = Date.now();
  }), []);
  React.useEffect(() => subscribeState((s) => setState(s)), []);

  React.useEffect(() => {
    const id = setInterval(() => {
      const d = liveRef.current;
      if (d) {
        setT(mapTelemetry(d));
        setUserPrompts(Array.isArray(d.user_prompts) ? d.user_prompts : []);
      }
      setFresh(Date.now() - lastRef.current < STALE_MS);
    }, 400);
    return () => clearInterval(id);
  }, []);

  // Periodic /status seed for the fields not on the /ws frame (fault_code,
  // versions) + a fallback when the socket is down.
  React.useEffect(() => {
    let alive = true;
    const pull = async () => {
      const s = await apiGet('/status');
      if (alive && s) {
        setStatus(s);
        if (s.state) setState(s.state);
        // If the socket hasn't delivered, seed t from the REST telemetry too.
        if (!liveRef.current && s.telemetry) setT(mapTelemetry(s.telemetry));
      }
    };
    pull();
    const id = setInterval(pull, 5000);
    return () => { alive = false; clearInterval(id); };
  }, []);

  return {
    t, state, fresh, userPrompts,
    connected: fresh || !!(status && status.connected),
    faultCode: status ? status.fault_code : undefined,
    faultMessage: status ? status.fault_message : undefined,
    fwVersion: status ? status.fw_version : undefined,
    hostVersion: status ? status.host_version : undefined,
    materialLowKg: status ? status.material_low_threshold_kg : undefined,
  };
}
