// Host-owned install + self-update UX for the phone PWA. Lives outside the design
// component (MobileMonitor.jsx) so a fresh design export never disturbs it.
//
// Why this is enough (vs the host/FW OTA): the app is SERVED by the host and the
// service worker is network-first, so a redeploy of the host (which rebuilds the
// mobile bundle) is already the "update" — the phone gets the new code on the next
// launch, no reinstall. This module just surfaces it nicely:
//   • an in-page Install button (so it's one tap, not a hidden browser menu), and
//   • a "new version — tap to update" banner when the host version changes under a
//     running app, so the operator doesn't have to know to close/reopen it.
import React from 'react';
import { apiGet } from '../src/api.js';
import { STANDALONE } from './machine-address.jsx';

// What "a new version of the app" means depends on who serves the app:
//   • machine-served (/m): the bundle ships with the host, so the host version
//     changing IS a new bundle → poll /status.host_version.
//   • standalone (hosted off-machine): the app updates when the STATIC HOST is
//     redeployed, independently of the machine → poll our own version.json,
//     which build-mobile.mjs --standalone stamps next to the bundle. This also
//     keeps working while the machine is unreachable.
async function fetchAppVersion() {
  if (!STANDALONE) {
    const s = await apiGet('/status');
    return s && s.host_version ? s.host_version : null;
  }
  try {
    const res = await fetch(new URL('version.json', location.href), { cache: 'no-store' });
    if (!res.ok) return null;
    const v = await res.json();
    return v && v.build ? String(v.build) : null;
  } catch { return null; }
}

// --- Install to home screen ------------------------------------------------
// Chrome fires `beforeinstallprompt` when the PWA is installable; we stash it and
// trigger it from our own button. Hidden once installed / on iOS (no event).
export function useInstallPrompt() {
  const [deferred, setDeferred] = React.useState(null);
  const [installed, setInstalled] = React.useState(
    () => window.matchMedia('(display-mode: standalone)').matches
       || window.navigator.standalone === true);

  React.useEffect(() => {
    const onPrompt = (e) => { e.preventDefault(); setDeferred(e); };
    const onInstalled = () => { setInstalled(true); setDeferred(null); };
    window.addEventListener('beforeinstallprompt', onPrompt);
    window.addEventListener('appinstalled', onInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', onPrompt);
      window.removeEventListener('appinstalled', onInstalled);
    };
  }, []);

  const install = React.useCallback(async () => {
    if (!deferred) return;
    deferred.prompt();
    try { await deferred.userChoice; } catch { /* ignore */ }
    setDeferred(null);
  }, [deferred]);

  return { canInstall: !!deferred && !installed, install, installed };
}

// --- Self-update watch -----------------------------------------------------
// Records the host version the running bundle booted against, then polls it. When
// it changes, a newer mobile bundle is being served → offer a reload (network-first
// SW fetches the fresh code). Mirrors the host/FW check→notify→apply flow; "apply"
// for a served PWA is simply a reload.
export function useAppUpdate(pollMs = 20000) {
  const [current, setCurrent] = React.useState(null);
  const bootRef = React.useRef(null);

  React.useEffect(() => {
    let alive = true;
    const check = async () => {
      const v = await fetchAppVersion();
      if (!alive || !v) return;
      if (bootRef.current == null) bootRef.current = v;   // pin at boot
      setCurrent(v);
    };
    check();
    const id = setInterval(check, pollMs);
    return () => { alive = false; clearInterval(id); };
  }, [pollMs]);

  const updateAvailable = current != null && bootRef.current != null
    && current !== bootRef.current;

  // Reload into the fresh bundle. Drop the service-worker caches first so a
  // reload can't be served the old shell, then hard-navigate.
  const apply = React.useCallback(async () => {
    try {
      if ('serviceWorker' in navigator) {
        const regs = await navigator.serviceWorker.getRegistrations();
        await Promise.all(regs.map((r) => r.update().catch(() => {})));
      }
      if (window.caches && caches.keys) {
        const keys = await caches.keys();
        await Promise.all(keys.map((k) => caches.delete(k)));
      }
    } catch { /* best-effort */ }
    window.location.reload();
  }, []);

  return { updateAvailable, version: current, apply };
}

// --- The bar shown above the monitor ---------------------------------------
// Renders nothing unless there's something to offer. Slim, theme-matched, sticky
// at the very top so it never fights the design's own in-app banners.
export function UpdateBar() {
  const { canInstall, install } = useInstallPrompt();
  const { updateAvailable, apply } = useAppUpdate();

  if (!updateAvailable && !canInstall) return null;

  const barStyle = {
    display: 'flex', alignItems: 'center', gap: 10,
    padding: 'calc(env(safe-area-inset-top, 0px) + 8px) 14px 8px',
    fontSize: 14, fontWeight: 600,
  };
  const btn = (bg, fg) => ({
    marginLeft: 'auto', border: 'none', borderRadius: 10, padding: '8px 14px',
    minHeight: 40, font: 'inherit', fontWeight: 700, background: bg, color: fg,
  });

  if (updateAvailable) {
    return (
      <div style={{ ...barStyle, background: 'var(--accent)', color: '#04121f' }}>
        <span>New version available</span>
        <button style={btn('#04121f', '#e7edf3')} onClick={apply}>Update</button>
      </div>
    );
  }
  return (
    <div style={{ ...barStyle, background: 'var(--panel-2)', color: 'var(--text)',
      borderBottom: '1px solid var(--line)' }}>
      <span>Add FT2 to your home screen</span>
      <button style={btn('var(--accent)', '#04121f')} onClick={install}>Install</button>
    </div>
  );
}
