// Minimal client for the FastAPI backend.
//   subscribeTelemetry(fn) — fn(data) on every /ws telemetry frame.
//   apiPost(path, body)    — REST control write (used in the control-wiring phase).
//
// Default transport is SAME-ORIGIN: the LCD kiosk and the machine-served /m app
// are both served by the API, so host/port are implicit and nothing below has to
// be configured. The phone app can also be hosted OFF the machine (a static host
// on the tailnet), in which case there is no such origin — it stores the machine
// address once and every URL here is built against it. See setBaseUrl().

// --- Machine address (base URL) --------------------------------------------
// '' (the default) = same origin. Anything else is an absolute origin like
// "https://ft2-machine-b1.tailaf20f5.ts.net". Stored in localStorage so the
// installed app remembers which machine it points at across launches.
const BASE_KEY = 'ft2_machine_url';
let _base = '';
try { _base = localStorage.getItem(BASE_KEY) || ''; } catch { /* private mode */ }

/** Absolute machine origin, or '' when we're served by the machine itself. */
export function getBaseUrl() { return _base; }

/** Normalize what a user typed into an origin: "ft2-machine-b1:8000" →
 *  "<page protocol>//ft2-machine-b1:8000". Returns '' for empty input. */
export function normalizeBaseUrl(input) {
  const s = (input || '').trim().replace(/\/+$/, '');
  if (!s) return '';
  const withScheme = /^https?:\/\//i.test(s)
    ? s
    : `${location.protocol === 'https:' ? 'https:' : 'http:'}//${s}`;
  try { return new URL(withScheme).origin; } catch { return ''; }
}

/** Point the app at a machine. Changing it drops the session token — a token
 *  is issued by one machine and means nothing to another. Callers re-gate. */
export function setBaseUrl(url) {
  const next = normalizeBaseUrl(url);
  if (next === _base) return next;
  clearToken();
  _base = next;
  try {
    if (next) localStorage.setItem(BASE_KEY, next);
    else localStorage.removeItem(BASE_KEY);
  } catch { /* ignore */ }
  if (_ws) { try { _ws.close(); } catch { /* ignore */ } _ws = null; }
  return next;
}

/** True when the app is hosted somewhere the machine can't be reached from:
 *  an https page may not talk to an http machine (browsers block it). */
export function isMixedContentBlocked(url) {
  const b = url === undefined ? _base : normalizeBaseUrl(url);
  return location.protocol === 'https:' && b.startsWith('http://');
}

/** Absolute URL for an API path. Also what an <img>/<a> needs (camera stream). */
export function apiUrl(path) { return _base ? `${_base}${path}` : path; }

let _ws = null;
const _subs = new Set();        // telemetry-frame subscribers
const _stateSubs = new Set();   // machine-state subscribers (IDLE/RUNNING/ESTOP/…)
const _autotuneSubs = new Set(); // autotune sample/result subscribers

function _emit(set, arg) {
  for (const fn of set) { try { fn(arg); } catch { /* ignore */ } }
}

function _connect() {
  // ws:// for an http machine, wss:// for an https one — taken from the machine
  // address when we're hosted off-machine, else from the page we were served by.
  const origin = _base || location.origin;
  const proto = origin.startsWith('https:') ? 'wss:' : 'ws:';
  const host = origin.replace(/^https?:\/\//, '');
  // Browsers can't set headers on a WebSocket, so the session token rides as a
  // query param (the server validates it before accepting the socket).
  const t = getToken();
  const q = t ? `?token=${encodeURIComponent(t)}` : '';
  const ws = new WebSocket(`${proto}//${host}/ws${q}`);
  ws.onmessage = (e) => {
    let msg;
    try { msg = JSON.parse(e.data); } catch { return; }
    if (msg.type === 'telemetry') _emit(_subs, msg.data);
    else if (msg.type === 'state_change' && msg.data && msg.data.to)
      _emit(_stateSubs, msg.data.to);
    else if (msg.type === 'autotune_sample')
      _emit(_autotuneSubs, { kind: 'sample', ...msg.data });
    else if (msg.type === 'autotune_result')
      _emit(_autotuneSubs, { kind: 'result', ...msg.data });
  };
  ws.onclose = () => { _ws = null; setTimeout(_connect, 2000); };
  ws.onerror = () => { /* onclose handles reconnect */ };
  _ws = ws;
}

export function subscribeTelemetry(fn) {
  _subs.add(fn);
  if (!_ws) _connect();
  return () => _subs.delete(fn);
}

// Autotune stream. fn receives { kind: 'sample', heater_idx, temp } at ~10 Hz
// during tuning, then { kind: 'result', heater_idx, status, Kp, Ki, Kd, Ku, Tu }.
export function subscribeAutotune(fn) {
  _autotuneSubs.add(fn);
  if (!_ws) _connect();
  return () => _autotuneSubs.delete(fn);
}

// Machine state (IDLE/RUNNING/ESTOP/FAULT/…). Seeds from /status, then tracks
// state_change frames. Used to reconcile the UI's estop indicator with reality.
export function subscribeState(fn) {
  _stateSubs.add(fn);
  if (!_ws) _connect();
  apiGet('/status').then((s) => { if (s && s.state) fn(s.state); });
  return () => _stateSubs.delete(fn);
}

// --- Session auth ----------------------------------------------------------
// The user logs in once (Login screen → POST /auth/login) and we keep the
// returned token. "Remember on this computer" stores it in localStorage (it
// survives a browser restart); otherwise sessionStorage (cleared when the tab
// closes). The token rides as `Authorization: Bearer …` on every request.
const TOKEN_KEY = 'ft2_session';

export function getToken() {
  try {
    return localStorage.getItem(TOKEN_KEY) || sessionStorage.getItem(TOKEN_KEY) || null;
  } catch { return null; }
}

function setToken(token, remember) {
  try {
    localStorage.removeItem(TOKEN_KEY);
    sessionStorage.removeItem(TOKEN_KEY);
    (remember ? localStorage : sessionStorage).setItem(TOKEN_KEY, token);
  } catch { /* ignore */ }
}

export function clearToken() {
  try { localStorage.removeItem(TOKEN_KEY); sessionStorage.removeItem(TOKEN_KEY); }
  catch { /* ignore */ }
}

function _authHeaders(base) {
  const h = base || {};
  const t = getToken();
  if (t) h['Authorization'] = `Bearer ${t}`;
  return h;
}

// Raised when the server rejects our credential, so the app can fall back to
// the login screen. AuthGate (main.jsx) listens for it.
function _authRequired() {
  clearToken();
  try { window.dispatchEvent(new Event('ft2-auth-required')); } catch { /* ignore */ }
}

// Exchange a password for a session token. Returns {ok} or {ok:false, status}.
export async function login(password, remember) {
  try {
    const res = await fetch(apiUrl('/auth/login'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password, remember }),
    });
    if (!res.ok) return { ok: false, status: res.status };
    const data = await res.json();
    setToken(data.token, remember);
    return { ok: true };
  } catch { return { ok: false, status: 0 }; }
}

export function logout() { _authRequired(); }

// 'ok' (proceed) | 'login' (show login) | 'offline' (backend unreachable).
export async function checkAuth() {
  try {
    const res = await fetch(apiUrl('/auth/verify'), { headers: _authHeaders() });
    if (res.ok) return 'ok';
    if (res.status === 401) return 'login';
    return 'offline';
  } catch { return 'offline'; }
}

export async function apiGet(path) {
  try {
    const res = await fetch(apiUrl(path), { headers: _authHeaders() });
    if (res.status === 401) { _authRequired(); return null; }
    return res.ok ? await res.json() : null;
  } catch {
    return null;
  }
}

export async function apiPost(path, body) {
  const headers = _authHeaders();
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  try {
    const res = await fetch(apiUrl(path), {
      method: 'POST',
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });
    if (res.status === 401) { _authRequired(); return null; }
    return res.ok ? await res.json().catch(() => ({})) : null;
  } catch {
    return null;
  }
}
