// Per-station colour STATE for the schematic readouts, SHARED by the LCD
// (live-core.jsx) and the phone (mobile-core.jsx) so both show identical colours.
// Pure functions of the /ws frame values; the bands are the host-audit criteria.
// (Dancer tension states are computed host-side in tension_health.py and arrive as
// frame fields — they're not here.)
const num = (v) => typeof v === 'number';

// Heaters: off | heating | attemp | overtemp. ±5°C "at temp" band; over-temp at +5°C.
export const HEATER_BAND_C = 5;
export function heaterState(enabled, temp, target) {
  if (!enabled || !num(temp) || !num(target) || target <= 0) return 'off';
  if (temp > target + HEATER_BAND_C) return 'overtemp';
  if (temp >= target - HEATER_BAND_C) return 'attemp';
  return 'heating';
}

// Puller: off | atspeed | offspeed. Dim when not moving; symmetric ±0.25 m/min.
// Both args are m/min.
export const PULLER_BAND_M = 0.25;
export function pullerState(measuredMmin, setpointMmin) {
  if (!num(measuredMmin) || measuredMmin < 0.05) return 'off';
  if (!num(setpointMmin)) return 'atspeed';
  return Math.abs(measuredMmin - setpointMmin) <= PULLER_BAND_M ? 'atspeed' : 'offspeed';
}

// Pump: off | building | atpressure | deviation. Symmetric ±8 psi. Has memory —
// "building" until it first reaches pressure this run, then any >8 psi excursion
// (stall drop or over-pressure) is a "deviation". So make ONE per UI (the closure
// holds the reached flag); resets when the pump stops.
export const PUMP_BAND_PSI = 8;
export function makePumpState() {
  let reached = false;
  return function pumpState(on, pressurePsi, setpointPsi) {
    if (!on) { reached = false; return 'off'; }
    if (!num(pressurePsi) || !num(setpointPsi) || setpointPsi <= 0) return 'building';
    if (Math.abs(pressurePsi - setpointPsi) <= PUMP_BAND_PSI) { reached = true; return 'atpressure'; }
    return reached ? 'deviation' : 'building';
  };
}
