// Machine address — HOST-OWNED chrome (never touched by a design export).
//
// The phone app can be hosted two ways:
//   • BY the machine at /m — same origin, nothing to configure (base URL '').
//   • OFF the machine on a static host (the independent-app build) — there is no
//     API at the app's own origin, so on first launch it asks which machine to
//     talk to and stores that address (api.js setBaseUrl → localStorage).
//
// Only the standalone build asks: build-mobile.mjs --standalone defines
// __FT2_STANDALONE__ = true. The machine-served /m bundle is unchanged.
import React from 'react';
import {
  getBaseUrl, setBaseUrl, normalizeBaseUrl, isMixedContentBlocked, clearToken,
} from '../src/api.js';

/* eslint-disable no-undef */
export const STANDALONE =
  typeof __FT2_STANDALONE__ !== 'undefined' && __FT2_STANDALONE__;
/* eslint-enable no-undef */

/** Standalone build with no machine chosen yet → show MachineSetup first. */
export function needsSetup() { return STANDALONE && !getBaseUrl(); }

/** Host part of the stored address, for display ("ft2-machine-b1:8000"). */
export function machineLabel() {
  return getBaseUrl().replace(/^https?:\/\//, '') || 'this machine';
}

// Is anything answering at this address? Any HTTP response counts — /auth/verify
// 401s until we log in, and a 401 still proves the machine is there. Only a
// network-level failure (wrong host, not on the tailnet, machine off) throws.
async function probe(base) {
  try {
    await fetch(`${base}/auth/verify`, { method: 'GET', cache: 'no-store' });
    return true;
  } catch { return false; }
}

/** First-run / change-machine screen. onDone() once an address is committed. */
export function MachineSetup({ onDone, onCancel }) {
  // Prefill with the current address (if any) so a typo is a small edit.
  const [addr, setAddr] = React.useState(() => getBaseUrl().replace(/^https?:\/\//, ''));
  const [err, setErr] = React.useState('');
  const [busy, setBusy] = React.useState(false);
  // Set once a probe has failed, so the address can be saved anyway. Setting up
  // the app while the machine is switched off is a normal thing to do here —
  // being installable and configurable without the machine is the whole point —
  // so a failed probe is a warning, never a wall.
  const [unverified, setUnverified] = React.useState('');

  const commit = (base) => { setBaseUrl(base); onDone(); }; // drops any old token

  const submit = async (e) => {
    e.preventDefault();
    const base = normalizeBaseUrl(addr);
    if (!base) { setErr('Enter a machine address, e.g. ft2-machine-b1:8000'); return; }
    if (isMixedContentBlocked(base)) {
      setErr('This app is served over https, so it can only talk to an https '
           + 'machine address. Use the machine\'s https (Tailscale) name.');
      return;
    }
    setBusy(true); setErr(''); setUnverified('');
    const reachable = await probe(base);
    setBusy(false);
    if (reachable) { commit(base); return; }
    setErr('No answer at that address — the machine may be powered down, or '
         + 'Tailscale may be off on this phone.');
    setUnverified(base);
  };

  return (
    <div className="login">
      <h1>FT2</h1>
      <p>Which machine should this app monitor?</p>
      <form onSubmit={submit}>
        <input type="text" inputMode="url" autoCapitalize="none" autoCorrect="off"
          placeholder="ft2-machine-b1:8000" value={addr}
          onChange={(e) => setAddr(e.target.value)} autoFocus />
        <div className="err">{err}</div>
        <button className="btn primary" style={{ width: '100%' }} disabled={busy || !addr}>
          {busy ? 'Checking…' : 'Connect'}
        </button>
        {unverified && (
          <button type="button" className="btn" style={{ width: '100%', marginTop: 10 }}
            onClick={() => commit(unverified)}>Save it anyway</button>
        )}
        {onCancel && (
          <button type="button" className="btn ghost" style={{ width: '100%', marginTop: 10 }}
            onClick={onCancel}>Cancel</button>
        )}
      </form>
      <p className="muted center" style={{ fontSize: 13, marginTop: 16 }}>
        The address is the machine's name on your Tailscale network. It's stored on
        this phone — change it any time from the bottom of the screen.
      </p>
    </div>
  );
}

/** Footer line: which machine this app is pointed at, + a way to change it.
 *  Renders nothing in the machine-served build (there's only one machine then). */
export function MachineBar({ onChange }) {
  if (!STANDALONE) return null;
  return (
    <div className="center muted" style={{ fontSize: 12, padding: '18px 12px 8px' }}>
      machine: {machineLabel()}
      {' · '}
      <button className="btn ghost" style={{ minHeight: 0, padding: '2px 6px', fontSize: 12 }}
        onClick={onChange}>change</button>
    </div>
  );
}

/** Forget the machine (address + token) — used by "change machine". */
export function forgetMachine() { clearToken(); setBaseUrl(''); }
